    size = [0] * (n + 1)
    parent = [0] * (n + 1)

    def dfs(root, p):
        parent[root] = p
        size[root] = 1
        for nei in adj[root]:
            if nei != p:
                size[root] += dfs(nei, root)
        return size[root]

    dfs(1, -1)

    transformations = []

    def process(root, p):
        for nei in adj[root]:
            if nei != p:
                if size[nei] > size[root] // 2:
                    # Swap root and nei
                    transformations.append((root, nei, p))
                    root, nei = nei, root
                process(nei, root)

    process(1, -1)

    print(len(transformations))
